from collections import Counter


def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [[bg] * w for _ in range(h)]
    seen = [[False] * w for _ in range(h)]

    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or seen[r][c]:
                continue
            comp = [(r, c)]
            seen[r][c] = True
            for y, x in comp:
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and not seen[ny][nx]
                            and grid[ny][nx] == color):
                        seen[ny][nx] = True
                        comp.append((ny, nx))
            r0, r1 = min(y for y, x in comp), max(y for y, x in comp)
            c0, c1 = min(x for y, x in comp), max(x for y, x in comp)
            box_area = (r1 - r0 + 1) * (c1 - c0 + 1)
            # Large, nearly rectangular colored regions are the objects; sparse
            # isolated marks are distractors. Restore their rectangle over holes.
            if len(comp) >= 6 and box_area >= 6 and len(comp) / box_area >= 0.60:
                for y in range(r0, r1 + 1):
                    for x in range(c0, c1 + 1):
                        out[y][x] = color
    return out

